1	/**
2	 * r30 foam06 (`f30*` switches, qa/match/06/r30/foam06/NOTES.md) — Screen 06 foam + bubbles WHILE Benny swims, toward the approved
3	 * picture (references/06_crest_the_rinse_arch.png) and the user's storyboard (docs/briefs/2026-11-20-r30/USER_S06_STORYBOARD_R30.png):
4	 *   `&f30bank=1` big soft BUBBLY foam heaps piled along both banks (white-lilac soap-foam lobes of many sizes, glossy highlight,
5	 *                faint iridescent rim, bubble pores on the shaded side), replacing the rows of small `m06fclu` puffs. One instanced
6	 *                draw (+ one soft-rim pass). Every heap is capped as ONE unit on screen (no giant occluding blobs near the camera:
7	 *                a near heap reads like the painting's big corner clusters), far heaps collapse (LOD).
8	 *   `&f30bub=1`  LARGE iridescent soap bubbles floating in the air beside Benny and along the slide (clear film, rainbow rims, white
9	 *                window highlights), a fixed pool recycled ahead of Benny (no allocation per frame), on-screen size capped, never
10	 *                over Benny himself, drifting slowly downstream and bobbing.
11	 *   `&f30ring=1` a lacy white splash ring round Benny where he sits in the water + a few droplets flicking off at his sides.
12	 *   `&f30=1`     all three.
13	 * Shown only on Screen 06 once the camera has left the approved viewpoint (the approved start view = the projected picture, which
14	 * carries its own foam / bubbles / splash): everything grows in with match06's away() factor, so the start view is unchanged.
15	 * Colours are the approved picture's display values, written through the post-chain inverse like the rest of match06.
16	 * Without an `f30` switch buildFoam30() returns null and nothing is built.
17	 */
18	import * as THREE from 'three';
19	import { PROJ05_INVERSE } from '../vfx/waterRibbon';
20	import type { Course } from './course';
21	
22	/** the r6 river profile of assets/textures/match06/proj06.json (tiles.r6): water |l| <= WC, raised foam bank WC..WB (height HB) */
23	const WC = 2.3, WB = 3.6, HB = 0.18;
24	
25	export interface Foam30 {
26	  group: THREE.Group;
27	  /** once per sim step, after match06.setAway (it re-shows the old m06fclu lobes, which f30bank hides again) */
28	  update(o: { on: boolean; away: number; camera: THREE.PerspectiveCamera; benny: THREE.Vector3; s: number; time: number; renderer: THREE.WebGLRenderer; m06group: THREE.Object3D }): void;
29	}
30	
31	// ------------------------------------------------------------------------------------------------ bank heaps
32	const BANK_VERT = /* glsl */ `
33	attribute vec4 aB;   // lobe centre (world) + radius
34	attribute vec4 aC;   // heap foot centre (world) + heap radius
35	attribute float aS;  // >= 1 foam lobe, < 1 small bubble; fract = seed
36	uniform vec3 uCap;   // x = max heap radius on screen, y = max lobe radius on screen (fractions of the half-height), z = grow-in 0..1
37	uniform vec2 uFar;   // LOD: heaps fade (shrink) out between these camera distances (u)
38	varying vec2 vUv;
39	varying float vS;
40	varying float vPx;
41	void main() {
42	  vUv = uv * 2.0 - 1.0;
43	  vS = aS;
44	  float P = projectionMatrix[1][1];
45	  float zc = -(viewMatrix * vec4(aC.xyz, 1.0)).z;
46	  // the whole heap is scaled about its foot so it never covers more than uCap.x of the screen (near corners = big clusters,
47	  // not a wall of white); behind / at the camera and beyond uFar it collapses
48	  float k = min(1.0, uCap.x / max(aC.w * P / max(zc, 0.05), 1e-4)) * uCap.z;
49	  k *= smoothstep(0.4, 1.2, zc) * (1.0 - smoothstep(uFar.x, uFar.y, zc));
50	  vec4 mv = viewMatrix * vec4(aC.xyz + (aB.xyz - aC.xyz) * k, 1.0);
51	  float r = aB.w * k;
52	  float lp = r * P / max(-mv.z, 0.05);
53	  r *= min(1.0, uCap.y / max(lp, 1e-4));
54	  vPx = r * P / max(-mv.z, 0.05);
55	  r *= step(0.0012, vPx); // LOD: lobes under ~1 px are dropped
56	  mv.xy += position.xy * r * 2.0;
57	  gl_Position = projectionMatrix * mv;
58	}`;
59	// approved picture's foam heaps (display values): white tops (253,252,253), pale lilac (238,230,252), lilac-blue (191,192,250),
60	// cool shadow (159,172,247); pores = darker lilac-blue dots with a glint; glossy white highlight up-left; faint pink/cyan rim
61	const BANK_FRAG = /* glsl */ `
62	uniform vec4 uPjPost;
63	uniform vec2 uPjRes;
64	varying vec2 vUv;
65	varying float vS;
66	varying float vPx;
67	${PROJ05_INVERSE}
68	float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
69	void main() {
70	  float r = length(vUv);
71	  if (r > 1.0) discard;
72	#ifdef RIM
73	  if (r < 0.84) discard;
74	#else
75	  if (r > 0.9) discard;
76	#endif
77	  bool lobe = vS >= 1.0;
78	  float s = fract(vS);
79	  vec3 nrm = vec3(vUv, sqrt(max(0.0, 1.0 - r * r)));
80	  vec3 L = normalize(vec3(-0.40, 0.74, 0.55));
81	  float lt = dot(nrm, L);
82	  vec3 cSh = vec3(0.60, 0.66, 0.96), cMid = vec3(0.75, 0.75, 0.98), cLi = vec3(0.93, 0.90, 0.99), cW = vec3(0.995, 0.99, 0.995);
83	  vec3 col = mix(cSh, cMid, smoothstep(-0.35, 0.25, lt));
84	  col = mix(col, cLi, smoothstep(0.25, 0.62, lt));
85	  col = mix(col, cW, smoothstep(0.60, 0.90, lt));
86	  // bounce light from the cyan water on the underside
87	  col = mix(col, vec3(0.66, 0.80, 1.0), 0.35 * smoothstep(-0.2, -0.85, vUv.y) * smoothstep(0.2, -0.4, lt));
88	  if (lobe) {
89	    // bubble pores on the shaded part of a lobe (the painted froth), finer on lobes that are big on screen
90	    float cells = clamp(vPx * 70.0, 4.5, 15.0);
91	    vec2 q = vUv * cells + s * 17.0;
92	    vec2 id = floor(q), f = fract(q) - 0.5;
93	    vec2 jt = vec2(h21(id), h21(id + 7.3)) - 0.5;
94	    float pr = 0.12 + 0.13 * h21(id + 3.1);
95	    float pd = length(f - jt * 0.45);
96	    float pore = (1.0 - smoothstep(pr * 0.65, pr, pd)) * step(0.42, h21(id + 11.0)) * smoothstep(0.5, 0.05, lt) * smoothstep(0.98, 0.7, r);
97	    col = mix(col, cSh * 0.78, pore * 0.8);
98	    col = mix(col, cW, (1.0 - smoothstep(0.0, pr * 0.35, length(f - jt * 0.45 - vec2(-0.3, 0.3) * pr))) * pore * 0.75);
99	  }
100	  // glossy soap highlight: a crisp window up-left + a small glint
101	  float hl = smoothstep(0.24, 0.10, length((vUv - vec2(-0.38, 0.42)) * vec2(1.0, 1.35)));
102	  float hl2 = smoothstep(0.09, 0.03, length(vUv - vec2(0.40, -0.40)));
103	  col = mix(col, vec3(1.0), clamp((lobe ? 0.75 : 1.0) * hl + 0.55 * hl2, 0.0, 1.0));
104	  // faint iridescent rim (soap film seen edge-on): pink <-> cyan <-> lilac
105	  float ang = atan(vUv.y, vUv.x) + s * 6.2832;
106	  vec3 iri = 0.80 + 0.20 * cos(6.2832 * (vec3(0.0, 0.33, 0.67) + ang * 0.32 + r * 0.9));
107	  iri = mix(iri, vec3(0.98, 0.80, 1.0), 0.35);
108	  float fr = smoothstep(0.62, 0.98, r) * (0.4 + 0.6 * (1.0 - clamp(lt, 0.0, 1.0)));
109	  col = mix(col, iri, fr * (lobe ? 0.5 : 0.8));
110	  float a = 1.0;
111	#ifdef RIM
112	  a = 1.0 - smoothstep(0.88, 1.0, r);
113	#endif
114	  gl_FragColor = vec4(pjInverse(clamp(col, 0.0, 1.0)), a);
115	}`;
116	
117	// ------------------------------------------------------------------------------------------------ floating bubbles
118	const BUB_VERT = /* glsl */ `
119	attribute vec4 aP;  // centre (world) + radius (already capped / faded on the CPU)
120	attribute vec2 aA;  // alpha, seed
121	varying vec2 vP;
122	varying vec2 vA;
123	varying float vPx;
124	void main() {
125	  vP = position.xy * 2.0;
126	  vA = aA;
127	  vec4 mv = viewMatrix * vec4(aP.xyz, 1.0);
128	  vPx = aP.w * projectionMatrix[1][1] / max(-mv.z, 0.05);
129	  mv.xy += position.xy * 2.0 * aP.w * step(0.002, aA.x);
130	  gl_Position = projectionMatrix * mv;
131	}`;
132	// the painted bubbles: nearly clear lilac-tinted inside, a bright rainbow film toward the rim (pink up-left, cyan / blue down-right,
133	// a touch of gold), a thin bright outline, a big soft white window highlight up-left and a crisp white dot down-right
134	const BUB_FRAG = /* glsl */ `
135	uniform vec4 uPjPost;
136	uniform vec2 uPjRes;
137	uniform float uTime;
138	varying vec2 vP;
139	varying vec2 vA;
140	varying float vPx;
141	${PROJ05_INVERSE}
142	void main() {
143	  float d2 = dot(vP, vP);
144	  if (d2 > 1.0) discard;
145	  float d = sqrt(d2);
146	  float f = 1.0 - sqrt(1.0 - d2);              // 0 centre .. 1 silhouette
147	  float seed = vA.y;
148	  float sw = sin(vP.x * 3.1 + vP.y * 2.3 + uTime * 0.5 + seed * 20.0) * 0.5 + 0.5;
149	  float hue = f * 0.9 + 0.25 * sw - vP.x * 0.22 + vP.y * 0.28 + seed;
150	  vec3 film = 0.62 + 0.38 * cos(6.2832 * (hue + vec3(0.0, 0.36, 0.68)));
151	  film = mix(film, vec3(0.95, 0.70, 1.0), 0.25);           // toward the painting's pink-lilac
152	  vec3 cool = vec3(0.55, 0.85, 1.0);
153	  film = mix(film, cool, 0.35 * smoothstep(-0.2, 0.7, vP.x - vP.y));  // cyan down-right
154	  float rim = smoothstep(0.55, 0.98, d);
155	  float edge = smoothstep(0.90, 0.975, d) * (1.0 - smoothstep(0.975, 1.0, d));
156	  vec2 q1 = (vP - vec2(-0.36, 0.40)) * vec2(2.3, 3.2);
157	  float hl = exp(-dot(q1, q1) * 2.0);
158	  // the painted window: a curved crescent highlight hugging the upper-left rim
159	  float cres = smoothstep(0.62, 0.78, d) * (1.0 - smoothstep(0.86, 0.95, d)) * smoothstep(0.2, 0.85, -vP.x * 0.6 + vP.y * 0.8);
160	  vec2 q2 = vP - vec2(0.40, -0.44);
161	  float dot2 = exp(-dot(q2, q2) * 70.0);
162	  float small = 1.0 - smoothstep(0.006, 0.02, vPx);   // tiny bubbles: ring + glint only
163	  vec3 inside = vec3(0.86, 0.80, 1.0);
164	  vec3 col = mix(inside, film, rim);
165	  col = mix(col, vec3(1.0), clamp(edge * 0.55 + hl * (1.0 - 0.4 * small) + cres * 0.7 + dot2, 0.0, 1.0));
166	  float a = 0.10 + 0.08 * sw + rim * 0.62 + edge * 0.3 + hl * 0.85 + cres * 0.6 + dot2;
167	  a = clamp(a, 0.0, 0.96) * vA.x;
168	  gl_FragColor = vec4(pjInverse(clamp(col, 0.0, 1.0)), a);
169	}`;
170	
171	// ------------------------------------------------------------------------------------------------ lace splash ring
172	const RING_VERT = /* glsl */ `
173	varying vec2 vL;
174	void main() {
175	  vL = position.xy;
176	  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
177	}`;
178	// local frame: x = river right, y = downstream, ring in the water plane. Lace = a white frothy band hugging the body, wider at the
179	// sides, broken into holes (lace) with a beaded outer edge, slowly churning
180	const RING_FRAG = /* glsl */ `
181	uniform vec4 uPjPost;
182	uniform vec2 uPjRes;
183	uniform float uTime;
184	uniform vec3 uRing;  // body waterline radius, band width, alpha
185	varying vec2 vL;
186	${PROJ05_INVERSE}
187	float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
188	float vn(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
189	  return mix(mix(h21(i), h21(i + vec2(1, 0)), f.x), mix(h21(i + vec2(0, 1)), h21(i + vec2(1, 1)), f.x), f.y); }
190	void main() {
191	  float rho = length(vL), th = atan(vL.y, vL.x);
192	  float side = abs(cos(th));                       // 1 at his left / right, 0 ahead / behind
193	  float R0 = uRing.x, w = uRing.y * (0.75 + 0.6 * side);
194	  float u = (rho - R0) / w;                        // 0 at the body .. 1 at the band's outer edge
195	  if (u < -0.15 || u > 1.6) discard;
196	  float n1 = vn(vec2(th * 9.0 + uTime * 0.6, rho * 9.0 - uTime * 1.3));
197	  float n2 = vn(vec2(th * 23.0 - uTime * 0.9, rho * 22.0 + uTime * 0.7));
198	  float lace = smoothstep(0.38, 0.55, 0.62 * n1 + 0.38 * n2 + 0.25 * (1.0 - u));   // holes
199	  float band = smoothstep(-0.15, 0.08, u) * (1.0 - smoothstep(0.55 + 0.35 * n1, 1.0 + 0.25 * n2, u));
200	  // beads on the outer edge: a ring of small droplets
201	  float cells = 46.0 + 10.0 * side;
202	  float cid = floor((th / 6.2832 + 0.5) * cells);
203	  float cf = fract((th / 6.2832 + 0.5) * cells) - 0.5;
204	  float bu = 1.05 + 0.35 * h21(vec2(cid, 3.0));
205	  float bead = (1.0 - smoothstep(0.18, 0.30, length(vec2(cf * 6.2832 * rho / cells * 2.0 / w, (u - bu) * 1.6)))) * step(0.35, h21(vec2(cid, 9.0)));
206	  float m = max(band * lace, bead * 0.9);
207	  if (m < 0.02) discard;
208	  vec3 col = mix(vec3(0.78, 0.93, 1.0), vec3(1.0), smoothstep(0.3, 0.9, n2 + 0.3 * (1.0 - u)));
209	  gl_FragColor = vec4(pjInverse(col), m * uRing.z);
210	}`;
211	const DROP_VERT = /* glsl */ `
212	attribute float aSize;
213	uniform float uScale;
214	varying float vA;
215	void main() {
216	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
217	  gl_PointSize = aSize > 0.0 ? clamp(aSize * uScale / max(-mv.z, 0.05), 1.5, 14.0) : 0.0;
218	  vA = aSize > 0.0 ? 1.0 : 0.0;
219	  gl_Position = projectionMatrix * mv;
220	}`;
221	const DROP_FRAG = /* glsl */ `
222	uniform vec4 uPjPost;
223	uniform vec2 uPjRes;
224	uniform float uAlpha;
225	varying float vA;
226	${PROJ05_INVERSE}
227	void main() {
228	  vec2 c = gl_PointCoord - 0.5;
229	  float d = length(c) * 2.0;
230	  if (d > 1.0 || vA < 0.5) discard;
231	  vec3 col = mix(vec3(1.0), vec3(0.70, 0.90, 1.0), smoothstep(0.4, 1.0, d));
232	  col = mix(col, vec3(1.0), smoothstep(0.35, 0.0, length(c - vec2(-0.12, -0.12))));
233	  gl_FragColor = vec4(pjInverse(col), (1.0 - smoothstep(0.75, 1.0, d)) * uAlpha);
234	}`;
235	
236	export function buildFoam30(course: Course): Foam30 | null {
237	  if (typeof location === 'undefined') return null;
238	  const qs = new URLSearchParams(location.search);
239	  const all = qs.get('f30') === '1';
240	  const BANK = all || qs.get('f30bank') === '1', BUB = all || qs.get('f30bub') === '1', RING = all || qs.get('f30ring') === '1';
241	  if (!BANK && !BUB && !RING) return null;
242	  const num = (k: string, d: number) => { const v = qs.get(k); return v !== null && v !== '' && Number.isFinite(+v) ? +v : d; };
243	  const st = course.stage('06');
244	  const group = new THREE.Group();
245	  group.name = 'm06_f30';
246	  group.visible = false;
247	  // shared post-chain inverse (the match06 default grade; exposure + buffer size follow the renderer)
248	  const uPjPost = { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) }, uPjRes = { value: new THREE.Vector2(864, 1536) };
249	  const uTime = { value: 0 };
250	  const quad = new THREE.PlaneGeometry(1, 1);
251	  let seed = 30061; const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
252	
253	  // ---- bank heaps (static, instanced)
254	  let bankU: { uCap: { value: THREE.Vector3 } } | null = null;
255	  const bankObjs: THREE.Mesh[] = [];
256	  if (BANK) {
257	    const hs = num('f30bs', 1), hn = num('f30bn', 1);
258	    const aB: number[] = [], aC: number[] = [], aS: number[] = [];
259	    const t1 = new THREE.Vector3();
260	    for (const side of [-1, 1]) {
261	      let s = st.s0 + 1 + rnd() * 1.5;
262	      while (s < st.s1 + 2) {
263	        const big = rnd() < 0.22;
264	        const Rh = (0.55 + 0.45 * rnd()) * (big ? 1.35 : 1) * hs;   // heap radius (u)
265	        const Hh = (0.32 + 0.3 * rnd()) * (big ? 1.3 : 1) * hs;     // heap height (u)
266	        const fr = course.sample(s);
267	        const lc = side * Math.min(WC + 0.45 + 0.5 * rnd(), WB + 0.1 - 0.75 * Rh); // on the raised bank, spilling a little onto the water
268	        const foot = fr.pos.clone().addScaledVector(fr.right, lc).addScaledVector(fr.up, HB - 0.06);
269	        t1.copy(fr.tan).normalize();
270	        const n = Math.max(8, Math.min(46, Math.round((10 + 30 * Rh) * hn)));
271	        for (let i = 0; i < n; i++) {
272	          const lobe = i < 3 || rnd() < 0.55;
273	          const th = rnd() * Math.PI * 2, dd = Math.sqrt(rnd());
274	          const du = Math.cos(th) * dd * Rh * 1.3, dl = Math.sin(th) * dd * Rh * 0.75;   // elongated along the bank
275	          const dome = Hh * Math.sqrt(Math.max(0, 1 - dd * dd));
276	          const rho = lobe ? Rh * (0.20 + 0.22 * rnd()) * (1 - 0.35 * dd) : Rh * (0.05 + 0.08 * Math.pow(rnd(), 1.4));
277	          const hgt = lobe ? Math.max(rho * 0.35, dome * (0.55 + 0.45 * rnd()) - rho * 0.25) : dome * (0.4 + 0.6 * rnd()) + rho * 0.4;
278	          const p = foot.clone().addScaledVector(t1, du).addScaledVector(fr.right, dl).addScaledVector(fr.up, hgt);
279	          aB.push(p.x, p.y, p.z, rho); aC.push(foot.x, foot.y, foot.z, Rh * 1.3 + Hh * 0.3); aS.push(rnd() * 0.999 + (lobe ? 1 : 0));
280	        }
281	        s += (big ? 1.5 : 1.0) * Rh * 2.0 * (0.75 + 0.5 * rnd()) + (rnd() < 0.2 ? 0.8 + rnd() * 1.4 : 0); // close piles, a few gaps
282	      }
283	    }
284	    const g = new THREE.InstancedBufferGeometry();
285	    g.setIndex(quad.index); g.setAttribute('position', quad.attributes.position); g.setAttribute('uv', quad.attributes.uv);
286	    g.setAttribute('aB', new THREE.InstancedBufferAttribute(new Float32Array(aB), 4));
287	    g.setAttribute('aC', new THREE.InstancedBufferAttribute(new Float32Array(aC), 4));
288	    g.setAttribute('aS', new THREE.InstancedBufferAttribute(new Float32Array(aS), 1));
289	    g.instanceCount = aS.length;
290	    const uCap = { value: new THREE.Vector3(num('f30bc', 0.24), num('f30bl', 0.065), 0) };
291	    const uFar = { value: new THREE.Vector2(55, 75) };
292	    bankU = { uCap };
293	    for (const rim of [false, true]) {
294	      const m = new THREE.ShaderMaterial({ vertexShader: BANK_VERT, fragmentShader: (rim ? '#define RIM\n' : '') + BANK_FRAG,
295	        transparent: rim, depthWrite: !rim, fog: false, uniforms: { uPjPost, uPjRes, uCap, uFar } });
296	      const o = new THREE.Mesh(g, m);
297	      o.name = rim ? 'f30_bank_rim' : 'f30_bank'; o.frustumCulled = false; o.renderOrder = rim ? 4 : 3;
298	      group.add(o); bankObjs.push(o);
299	    }
300	    console.info('[f30] bank', { lobes: aS.length });
301	  }
302	
303	  // ---- floating bubbles (pool, recycled ahead of Benny)
304	  interface Bub { s: number; l: number; h: number; r: number; ph: number; seed: number; }
305	  const bubs: Bub[] = [];
306	  let bubMesh: THREE.Mesh | null = null, aP: THREE.InstancedBufferAttribute | null = null, aA: THREE.InstancedBufferAttribute | null = null;
307	  const WIN0 = -5, WIN = num('f30bw', 46);
308	  const capR = num('f30bcap', 0.062); // max bubble radius on screen (fraction of the half-height): ~95 px diameter at 1536
309	  if (BUB) {
310	    const nBig = Math.round(num('f30bbn', 30)), nSmall = Math.round(num('f30bsn', 34)), bs = num('f30bbs', 1);
311	    for (let i = 0; i < nBig + nSmall; i++) {
312	      const bigB = i < nBig;
313	      const side = rnd() < 0.5 ? -1 : 1;
314	      // beside the slide (over the foam banks and the lower walls) and some over the water's edges, at many heights
315	      const l = side * (bigB ? 1.2 + 3.2 * rnd() : 0.8 + 3.8 * rnd());
