  strip.name = 'f30_froth'; strip.frustumCulled = false; strip.renderOrder = 2;
  strip.visible = qs.get('f30strip') !== '0';
  group.add(strip);
  console.info('[f30] bank', { lobes: aS.length, stripVerts: sp.length / 3 });
}

